"functions": [
  {
    "name": "list",
    "type": "function",
    "min_manifest_version": 3,
    "description": "Gets all messages in a folder.",
    "async": "callback",
    "permissions": ["accountsRead"],
    "parameters": [
      {
        "name": "folderId",
        "$ref": "folders.MailFolderId"
      },
      {
        "name": "options",
        "type": "object",
        "optional": true,
        "properties": {
          "sortType": {
            "type": "string",
            "description": "Specifies how the returned messages should be sorted. Default sort order is <var>descending</var>, if not specified otherwise. Returning sorted messages is faster than manually sorting the messages afterwards, but slower than returning the messages in their original order.",
            "optional": true,
            "enum": [
              "author",
              "date",
              "flagged",
              "junk",
              "junkScore",
              "priority",
              "read",
              "recipients",
              "size",
              "subject",
              "tags"
            ]
          },
          "sortOrder": {
            "type": "string",
            "description": "The sort order for the returned messages. Ignored if <var>sortType</var> is not specified.",
            "optional": true,
            "enum": ["ascending", "descending"]
          }
        }
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "$ref": "messages.MessageList"
          }
        ]
      }
    ]
  },
  {
    "name": "list",
    "type": "function",
    "max_manifest_version": 2,
    "description": "Gets all messages in a folder.",
    "async": "callback",
    "permissions": ["accountsRead"],
    "parameters": [
      {
        "name": "folder",
        "choices": [
          {
            "deprecated": "Support deprecated since Thunderbird 121 and removed in Manifest V3: messages.list() requires to specify a MailFolderId instead of a full MailFolder object.",
            "$ref": "folders.MailFolder"
          },
          {
            "$ref": "folders.MailFolderId"
          }
        ]
      },
      {
        "name": "options",
        "type": "object",
        "optional": true,
        "properties": {
          "sortType": {
            "type": "string",
            "description": "Specifies how the returned messages should be sorted. Default sort order is <var>descending</var>, if not specified otherwise. Returning sorted messages is faster than manually sorting the messages afterwards, but slower than returning the messages in their original order.",
            "optional": true,
            "enum": [
              "author",
              "date",
              "flagged",
              "junk",
              "junkScore",
              "priority",
              "read",
              "recipients",
              "size",
              "subject",
              "tags"
            ]
          },
          "sortOrder": {
            "type": "string",
            "optional": true,
            "description": "The sort order for the returned messages. Ignored if <var>sortType</var> is not specified.",
            "enum": ["ascending", "descending"]
          }
        }
      },
      {
        "type": "function",
        "name": "callback",
        "optional": true,
        "parameters": [
          {
            "$ref": "messages.MessageList"
          }
        ]
      }
    ]
